import{_ as i,a as r}from"./peer-turn-a1dccb92.js";import{_ as c}from"./plugin-vue_export-helper-c27b6911.js";import{r as o,o as l,c as u,d as s,e as n,b as e,w as p,a as d,f as k}from"./app-901c4b09.js";const h={},m=s("code",null,"dsh-peer",-1),v=s("strong",null,"how do you interject while the other agent is in the middle of a turn, and even abort it?",-1),g=s("p",null,[n('It took a while to see that DSH has three granularities of "sending a message": '),s("code",null,"prompt"),n(", "),s("code",null,"steer"),n(", and "),s("code",null,"cancel"),n(". The difference is not in the network layer — it is in the agent loop's "),s("strong",null,"turn/step boundaries"),n(".")],-1),b=k(`<h2 id="_1-a-peer-call-is-really-a-tool-call" tabindex="-1"><a class="header-anchor" href="#_1-a-peer-call-is-really-a-tool-call" aria-hidden="true">#</a> 1. A peer call is really a tool call</h2><p>To the model, <code>peer_ask</code> is an ordinary tool:</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>assistant: tool/call peer_ask { peer: &quot;macmini&quot;, prompt: &quot;run a long task&quot; }
tool:      peer_ask result { text: &quot;...&quot;, status: &quot;completed&quot;, elapsedMs: 42000 }
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>The remote side is a full runtime with its own model, tools, and session, but here it is wrapped as a function from prompt to final text. That abstraction has three gaps: no streaming, no reverse question, and no preemption. The first two were patched with a session mirror and an inbox; this post is about the third.</p><h2 id="_2-how-one-turn-actually-runs" tabindex="-1"><a class="header-anchor" href="#_2-how-one-turn-actually-runs" aria-hidden="true">#</a> 2. How one turn actually runs</h2><p>A turn consists of multiple steps; each step is one LLM request plus tool execution:</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>turn/start
  ├─ step 1: step/start → LLM request → tool/call → tool/result → step/end
  ├─ step 2: step/start → LLM request → ...
  └─ turn/end
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Before each step the driver claims messages from the <strong>inbox</strong>, which has two queues:</p><table><thead><tr><th>Queue</th><th>Written by</th><th>Consumed</th></tr></thead><tbody><tr><td><code>next-turn</code></td><td><code>prompt</code> / <code>followup</code></td><td>after the current turn, as the first input of the next turn</td></tr><tr><td><code>next-step</code></td><td><code>steer</code> / <code>inject</code></td><td><strong>before the next step starts</strong>, inside the current turn</td></tr></tbody></table><div class="language-typescript line-numbers-mode" data-ext="ts"><pre class="language-typescript"><code><span class="token function">followup</span><span class="token punctuation">(</span>message<span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token keyword">this</span><span class="token punctuation">.</span><span class="token function">send</span><span class="token punctuation">(</span>message<span class="token punctuation">,</span> <span class="token string">&#39;next-turn&#39;</span><span class="token punctuation">,</span> <span class="token boolean">true</span><span class="token punctuation">)</span> <span class="token punctuation">}</span>
<span class="token function">steer</span><span class="token punctuation">(</span>message<span class="token punctuation">)</span>    <span class="token punctuation">{</span> <span class="token keyword">this</span><span class="token punctuation">.</span><span class="token function">send</span><span class="token punctuation">(</span>message<span class="token punctuation">,</span> <span class="token string">&#39;next-step&#39;</span><span class="token punctuation">,</span> <span class="token boolean">true</span><span class="token punctuation">)</span> <span class="token punctuation">}</span>
<span class="token function">cancel</span><span class="token punctuation">(</span>cause<span class="token punctuation">)</span>     <span class="token punctuation">{</span> <span class="token comment">/* aborts the current activity */</span> <span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Details that are easy to miss:</p><ul><li><strong>steer does not interrupt the current step</strong> — running tools finish; the message is seen at the next step</li><li><strong>steer can keep a turn alive</strong> — if the model already decided to stop but <code>next-step</code> still has messages, the loop opens another step instead of breaking</li><li><strong>cancel keeps the queue</strong> — with <code>keepInbox: true</code>, queued steers survive for a later turn</li><li><strong>the inbox is durable</strong> — it is a session projection written into the session log, so it survives a restart</li></ul><p>So the three granularities are:</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>prompt  → next turn
steer   → next step (current turn continues)
cancel  → abort now (current turn ends)
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_3-protocol-design" tabindex="-1"><a class="header-anchor" href="#_3-protocol-design" aria-hidden="true">#</a> 3. Protocol design</h2><p>Three wire methods served by the link&#39;s <code>PeerHarnessServer</code>:</p><table><thead><tr><th>Method</th><th>Params</th><th>Result</th></tr></thead><tbody><tr><td><code>session/steer</code></td><td><code>{ sessionId, contentBlocks }</code></td><td><code>{ accepted, messageId }</code></td></tr><tr><td><code>session/cancel</code></td><td><code>{ sessionId, reason? }</code></td><td><code>{ cancelled, status }</code></td></tr><tr><td><code>session/state</code></td><td><code>{ sessionId }</code></td><td><code>{ status, seq }</code></td></tr></tbody></table><p>The link-side implementation is short; the important line is the ownership check — it only touches sessions this server created:</p><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token keyword">async</span> <span class="token function">handleRequest</span><span class="token punctuation">(</span><span class="token parameter">method<span class="token punctuation">,</span> params</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">if</span> <span class="token punctuation">(</span>method <span class="token operator">===</span> <span class="token string">&#39;session/steer&#39;</span><span class="token punctuation">)</span> <span class="token keyword">return</span> <span class="token keyword">this</span><span class="token punctuation">.</span><span class="token function">#steer</span><span class="token punctuation">(</span>params<span class="token punctuation">)</span>
  <span class="token keyword">if</span> <span class="token punctuation">(</span>method <span class="token operator">===</span> <span class="token string">&#39;session/cancel&#39;</span><span class="token punctuation">)</span> <span class="token keyword">return</span> <span class="token keyword">this</span><span class="token punctuation">.</span><span class="token function">#cancel</span><span class="token punctuation">(</span>params<span class="token punctuation">)</span>
  <span class="token keyword">if</span> <span class="token punctuation">(</span>method <span class="token operator">===</span> <span class="token string">&#39;session/state&#39;</span><span class="token punctuation">)</span> <span class="token keyword">return</span> <span class="token keyword">this</span><span class="token punctuation">.</span><span class="token function">#state</span><span class="token punctuation">(</span>params<span class="token punctuation">)</span>
  <span class="token keyword">return</span> <span class="token keyword">super</span><span class="token punctuation">.</span><span class="token function">handleRequest</span><span class="token punctuation">(</span>method<span class="token punctuation">,</span> params<span class="token punctuation">)</span>
<span class="token punctuation">}</span>

<span class="token function">#steer</span><span class="token punctuation">(</span><span class="token parameter">params</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">const</span> record <span class="token operator">=</span> <span class="token keyword">this</span><span class="token punctuation">.</span><span class="token function">#record</span><span class="token punctuation">(</span>params<span class="token punctuation">)</span>          <span class="token comment">// throws for unknown sessions</span>
  <span class="token keyword">const</span> message <span class="token operator">=</span> <span class="token function">createUserMessage</span><span class="token punctuation">(</span><span class="token punctuation">{</span> <span class="token literal-property property">content</span><span class="token operator">:</span> params<span class="token punctuation">.</span>contentBlocks<span class="token punctuation">,</span> <span class="token literal-property property">source</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token literal-property property">kind</span><span class="token operator">:</span> <span class="token string">&#39;user&#39;</span> <span class="token punctuation">}</span> <span class="token punctuation">}</span><span class="token punctuation">)</span>
  record<span class="token punctuation">.</span>handle<span class="token punctuation">.</span>agent<span class="token punctuation">.</span><span class="token function">steer</span><span class="token punctuation">(</span>message<span class="token punctuation">)</span>           <span class="token comment">// next-step</span>
  <span class="token keyword">return</span> <span class="token punctuation">{</span> <span class="token literal-property property">accepted</span><span class="token operator">:</span> <span class="token boolean">true</span><span class="token punctuation">,</span> <span class="token literal-property property">messageId</span><span class="token operator">:</span> message<span class="token punctuation">.</span>id <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>The hub routes and rate-limits:</p><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token keyword">async</span> <span class="token function">steer</span><span class="token punctuation">(</span><span class="token parameter">request</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">const</span> link <span class="token operator">=</span> <span class="token keyword">this</span><span class="token punctuation">.</span><span class="token function">require</span><span class="token punctuation">(</span>request<span class="token punctuation">.</span>peer<span class="token punctuation">)</span>
  <span class="token keyword">const</span> sessionId <span class="token operator">=</span> <span class="token keyword">this</span><span class="token punctuation">.</span><span class="token function">#sessionFor</span><span class="token punctuation">(</span>link<span class="token punctuation">,</span> request<span class="token punctuation">.</span>session<span class="token punctuation">,</span> <span class="token boolean">false</span><span class="token punctuation">)</span>
  <span class="token keyword">const</span> state <span class="token operator">=</span> <span class="token keyword">this</span><span class="token punctuation">.</span><span class="token function">#state</span><span class="token punctuation">(</span>link<span class="token punctuation">,</span> sessionId<span class="token punctuation">)</span>

  <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span><span class="token keyword">this</span><span class="token punctuation">.</span><span class="token function">#supportsSteer</span><span class="token punctuation">(</span>link<span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>             <span class="token comment">// version gate: &lt; 0.3.0 degrades</span>
    <span class="token keyword">return</span> <span class="token keyword">this</span><span class="token punctuation">.</span><span class="token function">#prompt</span><span class="token punctuation">(</span>link<span class="token punctuation">,</span> sessionId<span class="token punctuation">,</span> request<span class="token punctuation">.</span>text<span class="token punctuation">,</span> <span class="token string">&#39;prompt&#39;</span><span class="token punctuation">)</span>
  <span class="token punctuation">}</span>
  <span class="token keyword">if</span> <span class="token punctuation">(</span>state<span class="token punctuation">.</span>status <span class="token operator">===</span> <span class="token string">&#39;running&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">const</span> result <span class="token operator">=</span> <span class="token keyword">await</span> link<span class="token punctuation">.</span>conn<span class="token punctuation">.</span><span class="token function">request</span><span class="token punctuation">(</span><span class="token string">&#39;session/steer&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> sessionId<span class="token punctuation">,</span> contentBlocks <span class="token punctuation">}</span><span class="token punctuation">)</span>
    <span class="token keyword">return</span> <span class="token punctuation">{</span> <span class="token literal-property property">mode</span><span class="token operator">:</span> <span class="token string">&#39;steer&#39;</span><span class="token punctuation">,</span> <span class="token literal-property property">accepted</span><span class="token operator">:</span> result<span class="token punctuation">.</span>accepted<span class="token punctuation">,</span> <span class="token literal-property property">messageId</span><span class="token operator">:</span> result<span class="token punctuation">.</span>messageId <span class="token punctuation">}</span>
  <span class="token punctuation">}</span>
  <span class="token keyword">return</span> <span class="token keyword">this</span><span class="token punctuation">.</span><span class="token function">#prompt</span><span class="token punctuation">(</span>link<span class="token punctuation">,</span> sessionId<span class="token punctuation">,</span> request<span class="token punctuation">.</span>text<span class="token punctuation">,</span> <span class="token string">&#39;prompt&#39;</span><span class="token punctuation">)</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Two more constraints:</p><ul><li><strong>Version gate</strong>: links older than 0.3.0 get a prompt fallback for steer, and cancel fails loudly instead of hitting an unknown method</li><li><strong>Rate limit</strong>: 20 steer/cancel calls per peer per minute (<code>steerPerMinute</code>)</li></ul><h2 id="_4-why-a-reverse-question-always-arrives-a-turn-late" tabindex="-1"><a class="header-anchor" href="#_4-why-a-reverse-question-always-arrives-a-turn-late" aria-hidden="true">#</a> 4. Why a reverse question always arrives a turn late</h2><p>The hub&#39;s answer goes out as <code>session/prompt</code>, and the SDK server turns that into:</p><div class="language-typescript line-numbers-mode" data-ext="ts"><pre class="language-typescript"><code>rec<span class="token punctuation">.</span>handle<span class="token punctuation">.</span>agent<span class="token punctuation">.</span><span class="token function">followup</span><span class="token punctuation">(</span>message<span class="token punctuation">)</span>   <span class="token comment">// followup, not steer</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p><code>followup</code> lands in <code>next-turn</code>, so the answer is queued for the link&#39;s next turn:</p><figure><img src="`+i+'" alt="Why the answer arrives a turn late" tabindex="0" loading="lazy"><figcaption>Why the answer arrives a turn late</figcaption></figure><ul><li><code>peer_ask</code> / <code>peer_send</code> are just how the hub <strong>sends its answer</strong>; they are not a status query</li><li>the answer becomes a user message in the link&#39;s next turn</li><li>the link gets a delivery receipt, not the answer itself</li></ul><p>A true request/response needs either a suspended RPC or a link-side inbox plus <code>peer_wait</code>.</p><h2 id="_5-where-the-three-granularities-sit" tabindex="-1"><a class="header-anchor" href="#_5-where-the-three-granularities-sit" aria-hidden="true">#</a> 5. Where the three granularities sit</h2><figure><img src="'+r+`" alt="Peer turn / steer / cancel interaction" tabindex="0" loading="lazy"><figcaption>Peer turn / steer / cancel interaction</figcaption></figure><h2 id="_6-the-actual-steer-cancel-test" tabindex="-1"><a class="header-anchor" href="#_6-the-actual-steer-cancel-test" aria-hidden="true">#</a> 6. The actual steer / cancel test</h2><p>After macmini upgraded to 0.3.0:</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>peer_send(peer=&quot;macmini&quot;, prompt=&quot;for i in $(seq 1 90); do echo tick $i; sleep 1; done; echo DONE_LONG_TASK&quot;)
→ Queued on [macmini] session peer-macmini-chat (message ffbc6bf8-...)

sleep 6

peer_steer(peer=&quot;macmini&quot;, text=&quot;...STEER_OK...&quot;)
→ Steered into macmini; delivered at its next step.   (mode: &#39;steer&#39;)

peer_cancel(peer=&quot;macmini&quot;, reason=&quot;steer/cancel test&quot;)
→ Cancelled the current turn on macmini.              (cancelled: true)
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>The link stayed connected afterwards:</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>macmini (darwin/arm64, host ?, dsh 0.3.0) cwd=/Users/patrick
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>Two semantics to keep in mind:</p><ol><li><strong>steer&#39;s &quot;delivered&quot; means queued.</strong> While the 90-second command was still running, the message sat in <code>next-step</code>; the model would only see it after that step. We cancelled right after, so it stayed in the queue under <code>keepInbox: true</code> and will be consumed in the next turn — not lost.</li><li><strong>cancel aborts the turn, not the process.</strong> The running shell command may still finish; the agent stops advancing.</li></ol><h2 id="_7-the-bug-the-test-caught-a-missing-import" tabindex="-1"><a class="header-anchor" href="#_7-the-bug-the-test-caught-a-missing-import" aria-hidden="true">#</a> 7. The bug the test caught: a missing import</h2><p>macmini kept reporting silent handshake failures. It looked like a network issue, but it was one import:</p><div class="language-diff line-numbers-mode" data-ext="diff"><pre class="language-diff"><code><span class="token deleted-sign deleted"><span class="token prefix deleted">-</span><span class="token line"> import { PeerConnection, describeError, localIdentity } from &#39;./protocol.js&#39;
</span></span><span class="token inserted-sign inserted"><span class="token prefix inserted">+</span><span class="token line"> import { PeerConnection, PEER_VERSION, describeError, localIdentity } from &#39;./protocol.js&#39;
</span></span></code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p><code>link.js</code> used <code>PEER_VERSION</code> in <code>status()</code>, <code>peer/hello</code>, and reconnect state, but only <code>hub.js</code> imported it. Every dial threw a <code>ReferenceError</code> inside the handshake try/catch, was recorded as &quot;handshake failed&quot;, and retried with backoff — the real exception never reached the log.</p><p>Fix: <code>38f6c10</code> on <code>feat/session-mirror</code>.</p><p>The lesson matters more than the fix: <strong>on a cross-machine link, any error swallowed by a catch looks like a network problem.</strong> Keep the original exception at least at the handshake boundary.</p><h2 id="_8-what-is-still-missing" tabindex="-1"><a class="header-anchor" href="#_8-what-is-still-missing" aria-hidden="true">#</a> 8. What is still missing</h2><ul><li><strong>Code-level permission enforcement</strong>: peer-origin messages are still plain user messages, and a peer-woken turn runs with the user session&#39;s authority. The next step is to pin peer-origin turns to a restricted preset and require human approval for privileged actions.</li><li><strong>Link-side inbox / wait</strong>: a link can send, but cannot wait for the hub&#39;s answer within the same turn.</li><li><strong>Durable provenance</strong>: carry <code>origin</code> on the wire and store it in the message source instead of relying on a text prefix.</li></ul><h2 id="_9-takeaways" tabindex="-1"><a class="header-anchor" href="#_9-takeaways" aria-hidden="true">#</a> 9. Takeaways</h2><ul><li><code>prompt</code> / <code>steer</code> / <code>cancel</code> differ at the <strong>turn/step boundary</strong>, not on the wire</li><li>steer is &quot;next step&quot;, not an interrupt; cancel aborts the activity, not the process</li><li>a version gate and a rate limit are part of the protocol, not polish</li><li>when a cross-machine link misbehaves, suspect a swallowed exception before the network</li></ul><p>Code:</p>`,50),f={href:"https://github.com/SparksDing/dsh-peer",target:"_blank",rel:"noopener noreferrer"},w=s("code",null,"feat/session-mirror",-1),y={href:"https://github.com/SparksDing/deepseek-harness",target:"_blank",rel:"noopener noreferrer"},x=s("code",null,"feat/peer-session-mirror",-1);function _(q,T){const a=o("RouterLink"),t=o("ExternalLinkIcon");return l(),u("div",null,[s("p",null,[n("The "),e(a,{to:"/en/architecture/dsh-peer.html"},{default:p(()=>[n("previous post")]),_:1}),n(" covered "),m,n("'s connection direction and activity dashboard. This one goes after a narrower question: "),v]),g,s("blockquote",null,[s("p",null,[n("中文版: "),e(a,{to:"/architecture/dsh-peer-steer.html"},{default:p(()=>[n("给两个 agent 的对话加上 steer 与 cancel")]),_:1})])]),d(" more "),b,s("ul",null,[s("li",null,[s("a",f,[n("SparksDing/dsh-peer"),e(t)]),n(" ("),w,n(")")]),s("li",null,[n("fork: "),s("a",y,[n("SparksDing/deepseek-harness"),e(t)]),n(" ("),x,n(")")])])])}const j=c(h,[["render",_],["__file","dsh-peer-steer.html.vue"]]);export{j as default};
